/**
 * The plugin's settings page: an area rail, one area at a time, and search.
 *
 * Moodle renders this page as one long form. This module regroups the rows it already rendered --
 * it never creates or removes a control -- into areas, and shows them as a two-pane studio:
 *
 *   [ search            ]  [ area title, what it changes             ]
 *   [ About Dari        ]  [ setting ............ [ picture of it ] ]
 *   [ Look and colour   ]  [ setting ............ [ picture of it ] ]
 *   [ Course banner     ]  [ ...                                    ]
 *   [ ...               ]  [ ===== Save changes (sticky) ========== ]
 *
 * The rail is an ARIA tablist (vertical; a scrolling row on a phone) with roving tabindex and arrow
 * keys; each area is its tabpanel. Rows in an area that is not shown sit in a `hidden` panel, which
 * keeps them inside the form, so Save still submits every setting. Searching shows every area with
 * a match at once. A link to `#admin-<name>` (Moodle gives every row that id) opens the right area
 * and marks the row, and an area holding a validation error opens first after a failed save.
 *
 * @module     format_dari/settingsui
 * @copyright  2026 Dari Learning
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

import {buildSettingPreview} from 'format_dari/local/settingspreview';

/**
 * The areas.
 *
 * `match` is a list of patterns tested against the setting's own NAME, never its text, and the
 * first match wins -- so the ARRAY order is part of the matching logic (Timing before Cards, or
 * `hidetimesectioncards` files itself under Cards). `order` is what the reader sees.
 */
const CATEGORIES = [
    {
        id: 'time', order: 6, label: 'Estimated time', icon: 'time',
        desc: 'How long each activity is assumed to take, and which of the four places show the clock badges.',
        match: [/minutes/, /timing/, /hidetime/],
    },
    {
        id: 'tutor', order: 8, label: 'Ask Dari and AI images', icon: 'tutor',
        desc: 'Ask Dari and AI images. Both use your site\'s own AI provider (Site administration > '
            + 'General > AI); here you choose what course content is sent and how images look.',
        match: [/tutor/, /assessmentanswers/, /aiassistant/, /externalservice/, /aistatus/,
            /maxcontextchars/, /^direct/, /directheading/, /supportcontacts/, /sendfirstname/, /imagequality/, /imagestyle/, /aiscenewriter/, /adminreportlink/],
    },
    {
        id: 'tour', order: 9, label: 'First-visit tour', icon: 'tour',
        desc: 'The walkthrough someone sees the first time they open a course, and whether it is read aloud.',
        match: [/tour/],
    },
    {
        id: 'colour', order: 1, label: 'Look and colour', icon: 'colour',
        desc: 'The accent and every colour the format paints (headings, icons, cards, the side menu), '
            + 'plus your logo and light or dark mode.',
        match: [/colour/, /opacity/, /scrim/, /fade/, /overlay/, /playerlogo/, /colourmode/, /fontfamily/],
    },
    {
        id: 'index', order: 5, label: 'Course index', icon: 'index',
        desc: 'The side menu listing every section and activity: where it shows, how it opens, '
            + 'and whether it becomes a progress tracker.',
        match: [/playerindex/, /indexstate/, /playerheader/, /showcourseindex/, /^index/,
            /forceindex/, /defaultindex/, /hidegeneral/],
    },
    {
        id: 'banner', order: 2, label: 'Course banner', icon: 'banner',
        desc: 'The strip across the top of a course with its name and the learner\'s progress: '
            + 'whether it shows, its picture, and where it sits.',
        match: [/herobanner/, /heroattop/, /heroimage/, /herosticky/, /showherobanner/, /hero/],
    },
    {
        id: 'cards', order: 3, label: 'Section cards', icon: 'cards',
        desc: 'The tiles on the course home page, one per section: grid or list, title size, '
            + 'and which activities they list.',
        match: [/displayascards/, /cardlayout/, /cardtitlesize/, /cardactivitylimit/,
            /showactivities/, /card/],
    },
    {
        id: 'activity', order: 4, label: 'Inside a section', icon: 'activity',
        desc: 'How the activities on a section page are laid out, and the arrows that move a learner '
            + 'from one to the next.',
        match: [/activitydisplaymode/, /navchevrons/],
    },
    {
        id: 'nav', order: 7, label: 'Page furniture', icon: 'nav',
        desc: 'Moodle\'s own furniture around a course: the tabs, the breadcrumb trail, the footer '
            + 'and the site logo band.',
        match: [/secondarynav/, /coursenavplace/, /immersive/, /hidefooter/, /hidebreadcrumb/],
    },
    {
        id: 'other', order: 10, label: 'Everything else', icon: 'other',
        desc: 'Settings not claimed by an area above.',
        match: [],
    }
];

/** @type {String} Per-viewer memory of the open area, so it survives Save. */
const STORE_KEY = 'format_dari_settings_area';

/**
 * Which area a setting belongs to.
 *
 * @param {String} name The setting's own name.
 * @returns {Object} An entry from CATEGORIES; never null.
 */
const categoryOf = (name) => {
    for (const cat of CATEGORIES) {
        for (const pattern of cat.match) {
            if (pattern.test(name)) {
                return cat;
            }
        }
    }
    return CATEGORIES[CATEGORIES.length - 1];
};

/* --------------------------------------------------------------------------
   Icons. 24px line drawings, one per area, so nothing depends on an icon font
   or on how a platform draws a Unicode glyph.
   -------------------------------------------------------------------------- */
const ICONS = {
    about: '<circle cx="12" cy="12" r="9"/><path d="M12 11v6"/><path d="M12 7.5h.01"/>',
    colour: '<path d="M12 3c3.5 4 6 7.2 6 10.2A6 6 0 0 1 6 13.2C6 10.2 8.5 7 12 3z"/>'
        + '<path d="M9.5 14.5a2.6 2.6 0 0 0 2.5 2"/>',
    banner: '<rect x="3" y="5" width="18" height="9" rx="2"/><path d="M6 18h8"/><path d="M6 21h5"/>'
        + '<circle cx="17" cy="9.5" r="2"/>',
    cards: '<rect x="3.5" y="3.5" width="7.5" height="7.5" rx="2"/><rect x="13" y="3.5" width="7.5" height="7.5" rx="2"/>'
        + '<rect x="3.5" y="13" width="7.5" height="7.5" rx="2"/><rect x="13" y="13" width="7.5" height="7.5" rx="2"/>',
    activity: '<rect x="3.5" y="4" width="17" height="6" rx="2"/><rect x="3.5" y="14" width="17" height="6" rx="2"/>'
        + '<path d="m14 7 2 0"/><path d="m14 17 2 0"/>',
    index: '<rect x="3" y="4" width="18" height="16" rx="2.5"/><path d="M9 4v16"/><path d="M12.5 9h5"/>'
        + '<path d="M12.5 13h5"/><path d="M5.5 8h1"/><path d="M5.5 12h1"/>',
    time: '<circle cx="12" cy="13" r="8"/><path d="M12 9v4l2.5 2"/><path d="M10 2.5h4"/>',
    nav: '<rect x="3" y="3.5" width="18" height="17" rx="2.5"/><path d="M3 8.5h18"/><path d="M6 6h.01"/>'
        + '<path d="M8.5 6h.01"/><path d="M3 16.5h18"/>',
    tutor: '<path d="M12 3c.5 4.6 3.9 8 8.5 8.5-4.6.5-8 3.9-8.5 8.5-.5-4.6-3.9-8-8.5-8.5C8.1 11 11.5 7.6 12 3z"/>',
    tour: '<path d="M5 21V4"/><path d="M5 4h11l-2 3.5 2 3.5H5"/>',
    other: '<path d="M4 7h10"/><path d="M18 7h2"/><circle cx="16" cy="7" r="2"/><path d="M4 17h4"/>'
        + '<path d="M12 17h8"/><circle cx="10" cy="17" r="2"/>',
    search: '<circle cx="11" cy="11" r="6.5"/><path d="m20 20-4.2-4.2"/>',
};

/**
 * An inline SVG icon.
 *
 * Width and height are stated on the element as well as in CSS: an SVG with only a viewBox has
 * no intrinsic size, and without the stylesheet it would grow to fill its container.
 *
 * @param {String} key Key into ICONS.
 * @param {String} cls Class for the element.
 * @returns {String} Markup.
 */
const icon = (key, cls) =>
    '<svg class="' + cls + '" viewBox="0 0 24 24" width="20" height="20" aria-hidden="true" focusable="false" '
    + 'fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'
    + (ICONS[key] || ICONS.other) + '</svg>';

/**
 * Read a per-viewer value without letting blocked storage break the page.
 *
 * @returns {String|null}
 */
const recall = () => {
    try {
        return window.sessionStorage.getItem(STORE_KEY);
    } catch (e) {
        return null;
    }
};

/**
 * Remember a per-viewer value; silently skipped when storage is unavailable.
 *
 * @param {String} value The area id.
 * @returns {void}
 */
const remember = (value) => {
    try {
        window.sessionStorage.setItem(STORE_KEY, value);
    } catch (e) {
        // Storage blocked: the area simply is not remembered.
    }
};

/**
 * Build the page.
 *
 * @param {Object} strings Localised labels from PHP.
 * @returns {void}
 */
export const init = (strings) => {
    // English defaults so a stale language cache costs a word rather than the page.
    const t = Object.assign({
        search: 'Search settings…',
        nomatches: 'No settings match that search.',
        settings: 'settings',
        setting: 'setting',
        about: 'About this plugin',
        course: 'Course',
        appliestoall: 'Applies to every course that already exists',
        allcourses: 'All courses',
        current: 'Current'
    }, strings || {});

    // Only ever touch THIS plugin's settings page. `#adminsettings` exists on every admin settings
    // page, and settings.php is included while Moodle builds the whole admin tree, so the module
    // must prove where it is before it changes anything (settings.php carries the same guard).
    if (document.body.id !== 'page-admin-setting-formatsettingdari') {
        return;
    }

    const root = document.getElementById('adminsettings');
    if (!root || root.dataset.dsetDone === '1') {
        return;
    }

    // A setting is a row that PRINTS ITS OWN NAME (.form-shortname exists only for real settings).
    const settings = [];
    Array.from(root.querySelectorAll('.form-item')).forEach((item) => {
        const shortname = item.querySelector('.form-shortname');
        if (!shortname) {
            return;
        }
        const name = shortname.textContent.replace(/.*\|\s*/, '').trim();
        if (name === '') {
            return;
        }
        settings.push({item, name, cat: categoryOf(name),
            text: (name + ' ' + item.textContent).toLowerCase()});
    });

    if (settings.length < 4) {
        // Not this plugin's page, or a page that failed to render. Leave it alone.
        return;
    }
    root.dataset.dsetDone = '1';

    // Everything else the form shows -- headings, descriptions, the AI status, the report link --
    // gathered from wherever core put it: the form itself and the containers that hold the rows.
    const holders = new Set([root]);
    settings.forEach((s) => {
        let p = s.item.parentElement;
        while (p && p !== root) {
            holders.add(p);
            p = p.parentElement;
        }
    });
    const notes = [];
    holders.forEach((holder) => {
        Array.from(holder.children).forEach((el) => {
            if (holders.has(el) || settings.some((s) => s.item === el)) {
                return;
            }
            if (el.matches('input, script, style, .clearer, fieldset > legend')
                || el.querySelector('input[type="submit"], button[type="submit"]')
                || el.matches('h2') && el.parentElement && el.parentElement.classList.contains('settingsform')
                || el.textContent.trim() === '') {
                return;
            }
            notes.push(el);
        });
    });

    // A description row whose id names an area (admin-aistatus, admin-externalservicenotice...)
    // belongs at the top of that area, beside the settings it explains. Headings and anything
    // unclaimed form the "About" area.
    const areanotes = {};
    const aboutnotes = [];
    notes.forEach((el) => {
        const id = (el.id || '').replace(/^admin-/, '');
        // The documentation link (the Dari elephant) always opens the "About" area.
        if (id === 'docslink' || el.querySelector('.dari-docs-link')) {
            aboutnotes.unshift(el);
            return;
        }
        let cat = id && el.classList.contains('form-item') ? categoryOf(id) : null;
        // Moodle 5 renders description rows without an id. A description row explains the
        // settings that follow it, so it joins the area of the next real setting on the page.
        if (!cat && el.classList.contains('form-item')) {
            const next = settings.find((s) =>
                el.compareDocumentPosition(s.item) & Node.DOCUMENT_POSITION_FOLLOWING);
            cat = next ? next.cat : null;
        }
        if (cat && cat.id !== 'other') {
            (areanotes[cat.id] = areanotes[cat.id] || []).push(el);
        } else {
            aboutnotes.push(el);
        }
    });

    const display = CATEGORIES.slice().sort((a, b) => a.order - b.order);
    const areas = [];
    if (aboutnotes.length) {
        areas.push({id: 'about', label: t.about, icon: 'about', desc: '', rows: [], notes: aboutnotes});
    }
    display.forEach((cat) => {
        const rows = settings.filter((s) => s.cat.id === cat.id);
        if (!rows.length) {
            return;
        }
        areas.push(Object.assign({}, cat, {rows, notes: areanotes[cat.id] || []}));
    });

    // --- Shell -------------------------------------------------------------------------------
    const shell = document.createElement('div');
    shell.className = 'dset';

    const rail = document.createElement('div');
    rail.className = 'dset-rail';

    const search = document.createElement('div');
    search.className = 'dset-search';
    search.innerHTML = icon('search', 'dset-search-icon');
    const input = document.createElement('input');
    input.type = 'search';
    input.className = 'dset-search-input';
    input.placeholder = t.search;
    input.setAttribute('aria-label', t.search);
    input.setAttribute('aria-controls', 'dset-panes');
    search.appendChild(input);
    rail.appendChild(search);

    const tablist = document.createElement('div');
    tablist.className = 'dset-tabs';
    tablist.setAttribute('role', 'tablist');
    tablist.setAttribute('aria-orientation', 'vertical');
    tablist.setAttribute('aria-label', document.title || t.about);
    rail.appendChild(tablist);

    const panes = document.createElement('div');
    panes.className = 'dset-panes';
    panes.id = 'dset-panes';

    const status = document.createElement('p');
    status.className = 'dset-status';
    status.setAttribute('role', 'status');
    status.setAttribute('aria-live', 'polite');
    panes.appendChild(status);

    areas.forEach((area) => {
        const tab = document.createElement('button');
        tab.type = 'button';
        tab.className = 'dset-tab';
        tab.id = 'dset-tab-' + area.id;
        tab.setAttribute('role', 'tab');
        tab.setAttribute('aria-selected', 'false');
        tab.setAttribute('aria-controls', 'dset-pane-' + area.id);
        tab.tabIndex = -1;
        tab.innerHTML = icon(area.icon, 'dset-tab-icon')
            + '<span class="dset-tab-label"></span><span class="dset-tab-count"></span>';
        tab.querySelector('.dset-tab-label').textContent = area.label;
        const count = tab.querySelector('.dset-tab-count');
        if (area.rows.length) {
            count.textContent = String(area.rows.length);
        }
        tablist.appendChild(tab);

        const pane = document.createElement('section');
        pane.className = 'dset-pane dset-pane--' + area.id;
        pane.id = 'dset-pane-' + area.id;
        pane.setAttribute('role', 'tabpanel');
        pane.setAttribute('aria-labelledby', 'dset-title-' + area.id);
        pane.hidden = true;

        const head = document.createElement('header');
        head.className = 'dset-pane-head';
        head.innerHTML = '<span class="dset-pane-mark">' + icon(area.icon, 'dset-pane-icon') + '</span>'
            + '<div class="dset-pane-text"><h2 class="dset-pane-title" id="dset-title-' + area.id + '"></h2>'
            + '<p class="dset-pane-desc"></p></div>';
        head.querySelector('.dset-pane-title').textContent = area.label;
        const desc = head.querySelector('.dset-pane-desc');
        if (area.desc) {
            desc.textContent = area.desc;
        } else {
            desc.remove();
        }
        pane.appendChild(head);

        area.notes.forEach((n) => {
            n.classList.add('dset-note');
            pane.appendChild(n);
        });

        area.rows.forEach((s) => {
            s.item.classList.add('dset-setting');
            buildSettingPreview(s.name, s.item, t).forEach((el) => s.item.appendChild(el));
            pane.appendChild(s.item);
        });

        panes.appendChild(pane);
        area.tab = tab;
        area.pane = pane;
        area.count = count;
    });

    const empty = document.createElement('p');
    empty.className = 'dset-empty';
    empty.textContent = t.nomatches;
    empty.hidden = true;
    panes.appendChild(empty);

    shell.appendChild(rail);
    shell.appendChild(panes);
    root.appendChild(shell);

    // Save: moved to the end of the pane column and kept in view.
    const submit = root.querySelector('input[type="submit"], button[type="submit"]');
    if (submit) {
        const holder = submit.closest('.form-buttons, .row, .felement, div') || submit;
        holder.classList.add('dset-save');
        panes.appendChild(holder);
    }

    // --- Behaviour -----------------------------------------------------------------------------
    let current = null;

    /**
     * Show one area.
     *
     * @param {Object} area The area record.
     * @param {Boolean} focus Move focus to its tab.
     * @returns {void}
     */
    const select = (area, focus) => {
        current = area;
        areas.forEach((a) => {
            const on = a === area;
            a.tab.setAttribute('aria-selected', on ? 'true' : 'false');
            a.tab.tabIndex = on ? 0 : -1;
            a.pane.hidden = !on;
            a.rows.forEach((s) => {
                s.item.hidden = false;
            });
        });
        if (focus) {
            area.tab.focus();
        }
        remember(area.id);
    };

    areas.forEach((area, i) => {
        area.tab.addEventListener('click', () => {
            if (input.value) {
                input.value = '';
                filter('');
            }
            select(area, false);
        });
        area.tab.addEventListener('keydown', (e) => {
            const keys = {ArrowDown: 1, ArrowRight: 1, ArrowUp: -1, ArrowLeft: -1};
            let next = null;
            if (keys[e.key]) {
                const dir = (e.key === 'ArrowRight' || e.key === 'ArrowLeft')
                    && document.dir === 'rtl' ? -keys[e.key] : keys[e.key];
                next = areas[(i + dir + areas.length) % areas.length];
            } else if (e.key === 'Home') {
                next = areas[0];
            } else if (e.key === 'End') {
                next = areas[areas.length - 1];
            }
            if (next) {
                e.preventDefault();
                select(next, true);
            }
        });
    });

    /**
     * Filter every area by the search text. Searching shows all areas with a match at once, each
     * with only its matching rows; clearing it returns to the area that was open.
     *
     * @param {String} query Lower-cased search text.
     * @returns {void}
     */
    const filter = (query) => {
        shell.classList.toggle('is-searching', Boolean(query));
        if (!query) {
            status.textContent = '';
            empty.hidden = true;
            areas.forEach((a) => {
                a.tab.classList.remove('has-hits', 'no-hits');
                if (a.rows.length) {
                    a.count.textContent = String(a.rows.length);
                }
            });
            select(current || areas[0], false);
            return;
        }
        let total = 0;
        areas.forEach((a) => {
            let hits = 0;
            a.rows.forEach((s) => {
                const on = s.text.indexOf(query) !== -1;
                s.item.hidden = !on;
                hits += on ? 1 : 0;
            });
            const notehit = a.notes.some((n) => n.textContent.toLowerCase().indexOf(query) !== -1);
            a.pane.hidden = hits === 0 && !notehit;
            a.tab.classList.toggle('has-hits', hits > 0);
            a.tab.classList.toggle('no-hits', hits === 0 && !notehit);
            if (a.rows.length) {
                a.count.textContent = String(hits);
            }
            total += hits;
        });
        empty.hidden = total !== 0;
        status.textContent = total ? total + ' ' + (total === 1 ? t.setting : t.settings) : '';
    };

    let debounce = null;
    input.addEventListener('input', () => {
        window.clearTimeout(debounce);
        debounce = window.setTimeout(() => filter(input.value.trim().toLowerCase()), 120);
    });

    /**
     * Follow a #admin-<name> link: open the area that holds it and mark the row.
     *
     * @returns {Boolean} Whether a row was found.
     */
    const jump = () => {
        const hash = window.location.hash;
        if (!hash || hash.indexOf('#admin-') !== 0) {
            return false;
        }
        const name = hash.slice('#admin-'.length);
        const area = areas.find((a) => a.rows.some((s) => s.name === name));
        if (!area) {
            return false;
        }
        const row = area.rows.find((s) => s.name === name);
        if (input.value) {
            input.value = '';
            filter('');
        }
        select(area, false);
        row.item.classList.remove('dset-flash');
        void row.item.offsetWidth;
        row.item.classList.add('dset-flash');
        window.requestAnimationFrame(() => row.item.scrollIntoView({block: 'center', behavior: 'smooth'}));
        return true;
    };
    window.addEventListener('hashchange', jump);

    // First area: a link target, then any area holding a validation error from the last save,
    // then the one this person had open, then the first area that holds settings.
    const witherror = areas.find((a) => a.pane.querySelector('.error, .alert-danger, .is-invalid'));
    const stored = recall();
    select(witherror || areas.find((a) => a.id === stored)
        || areas.find((a) => a.rows.length) || areas[0], false);
    if (window.location.hash) {
        window.setTimeout(jump, 60);
    }
};
